import java.util.*;
import java.io.*;

public class EdE {
    public static void main(String[] args) throws Exception {
        int mod = 998244353;
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long k = sc.nextLong();

        long[] factorials = new long[200001];
        factorials[0] = 1;
        for (int i = 1; i <= 200000; i++) {
            factorials[i] = (factorials[i - 1] * i) % mod;
        }

        long sum = 0;
        for (int i = 0; i < n - k; i++) {
            long numerator = factorials[(int)(n - k)];
            long invI = modPow(factorials[i], mod - 2, mod);
            long invNMinusKMinusI = modPow(factorials[(int)(n - k - i)], mod - 2, mod);
            long comb = (numerator * invI) % mod;
            comb = (comb * invNMinusKMinusI) % mod;
            long val = modPow(n - k - i, n, mod);
            if (i % 2 == 0) {
                sum = (sum + comb * val) % mod;
            } else {
                sum = (sum - comb * val + mod) % mod;
            }
        }

        if (k >= n) {
            System.out.println(0);
        } else {
            if (k != 0) {
                sum = (sum * 2) % mod;
            }
            sum = (sum * factorials[(int) n]) % mod;
            sum = (sum * modPow(factorials[(int) k], mod - 2, mod)) % mod;
            sum = (sum * modPow(factorials[(int)(n - k)], mod - 2, mod)) % mod;
            System.out.println(sum);
        }
        sc.close();
    }

    public static long modPow(long base, long exp, int mod) {
        long result = 1;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }
}
